demolish_button_rect :: proc(pop: rl.Rectangle, v: ^View = nil) -> rl.Rectangle {
	// 7.3: the button insets scale with the knob when a view is available
	// (the caller passes it; the fallback keeps the old call sites working).
	if v != nil {
		return {pop.x + hud_f(v, 10), pop.y + pop.height - hud_f(v, 36), pop.width - hud_f(v, 20), hud_f(v, 26)}
	}
	return {pop.x + 10, pop.y + pop.height - 36, pop.width - 20, 26}
}  ---  harness/parity.odin:976: btn := rnd.demolish_button_rect(pop)
